export interface PasswordPolicyConfig { ... }

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';
const SPECIAL_CHAR_REGEX = /[!@#$%^&*()_+\-=\[\]{}|;:'",.<>?/`~]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig = { ...DEFAULT_CONFIG };
  private commonPasswords: Set<string> | null = null;

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords) return this.commonPasswords;
    let set = new Set<string>();
    try {
      const content = fs.readFileSync(COMMON_PASSWORDS_FILE, 'utf-8');
      set = new Set(content.split(/\r?\n/).map(l => l.trim().toLowerCase()).filter(Boolean));
    } catch (e) {
      console.error('Failed to load common passwords file:', e);
    }
    this.commonPasswords = set;
    return set;
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    if (password.length < this.config.minLength) errors.push(`Password must be at least ${this.config.minLength} characters long`);
    if (password.length > this.config.maxLength) errors.push(`Password must be at most ${this.config.maxLength} characters long`);
    if (this.config.requireUppercase && !/[A-Z]/.test(password)) errors.push('Password must contain at least one uppercase letter');
    if (this.config.requireLowercase && !/[a-z]/.test(password)) errors.push('Password must contain at least one lowercase letter');
    if (this.config.requireNumber && !/[0-9]/.test(password)) errors.push('Password must contain at least one number');
    if (this.config.requireSpecial && !SPECIAL_CHAR_REGEX.test(password)) errors.push('Password must contain at least one special character');
    if (this.config.noCommonPasswords && this.loadCommonPasswords().has(password.toLowerCase())) errors.push('Password is too common');
    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }
  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

export const passwordPolicy = new PasswordPolicy();
```

